      "Clean temporary audio": ["Tempor\xE4res Audio bereinigen", "Nettoyer les fichiers audio temporaires", "\u0423\u0434\u0430\u043B\u044F\u0442\u044C \u0432\u0440\u0435\u043C\u0435\u043D\u043D\u043E\u0435 \u0430\u0443\u0434\u0438\u043E", "\uC784\uC2DC \uC624\uB514\uC624 \uC815\uB9AC", "\u4E00\u6642\u97F3\u58F0\u30D5\u30A1\u30A4\u30EB\u3092\u524A\u9664", "Limpiar audio temporal", "Elimina audio temporaneo"],
      "Diagnostic logging": ["Diagnoseprotokoll", "Journal de diagnostic", "\u0416\u0443\u0440\u043D\u0430\u043B \u0434\u0438\u0430\u0433\u043D\u043E\u0441\u0442\u0438\u043A\u0438", "\uC9C4\uB2E8 \uB85C\uADF8", "\u8A3A\u65AD\u30ED\u30B0", "Registro de diagn\xF3stico", "Registro diagnostico"],
